import {esc,miniWeather,trendSummary} from './weather-tools.js';
export function createCommunityPulse(ctx){
 let data=null,at=0,busy=false,error='',who='',hidden=[];try{hidden=JSON.parse(localStorage.getItem('ms-hidden-posts')||'[]');if(!Array.isArray(hidden))hidden=[]}catch{};
 function html(){return `<div class="pulse-overview"><details class="pulse-discovery"><summary>Tendenze meteo e community</summary><section class="community-pulse" aria-label="Tendenze e sfide"><div class="pulse-heading"><h2>Succede nel tuo cielo</h2><a href="#sfide">Sfide delle città →</a></div><div class="pulse-content" id="pulse-content">${content()}</div></section></details><a href="#sfide" class="pulse-challenge-link">✧ Sfide città</a></div>`}
 function content(){const {weather,place}=ctx.get(),trend=trendSummary(weather);return `<div class="pulse-weather"><span class="pulse-label">TENDENZA METEO · ${esc(place.name)}</span><div>${miniWeather(weather?.current?.weather_code,weather?.current?.is_day!==0)}<b>${weather?Math.round(weather.current.temperature_2m)+'°':'—'}</b><span>${trend?.delta!=null?'Domani '+(trend.delta>0?'+':'')+(Math.round(trend.delta*10)/10||0)+'° sulla massima':'Previsioni della località selezionata'}</span></div><a href="#tendenze">Quando uscire? →</a><a href="#ripari">Luoghi coperti →</a></div><div class="pulse-topics"><span class="pulse-label">COMMUNITY · ULTIME 24 ORE</span>${error?`<p role="status">${esc(error)}</p>`:!data?'<p role="status">Leggo i contributi recenti…</p>':data.themes.length?`<div class="pulse-topic-buttons">${data.themes.slice(0,4).map(t=>`<button data-pulse-topic="${esc(t.kind)}"><b>${esc(t.kind)}</b><small>${t.posts} post · ${t.people} ${t.people===1?'persona':'persone'}</small></button>`).join('')}</div>`:'<p>Il primo argomento può partire da te. Condividi il cielo della tua zona.</p>'}<small>Conteggi dei post, non intensità degli eventi.</small></div>${data?.cities?.length?`<div class="pulse-cities"><span class="pulse-label">CITTÀ CHE CONDIVIDONO</span>${data.cities.slice(0,4).map(c=>`<button data-pulse-city="${esc(c.city)}"><b>${esc(c.city)}</b><span>${c.people} ${c.people===1?'persona':'persone'}</span></button>`).join('')}</div>`:''}`}
 async function load(){if(busy)return;busy=true;const user=ctx.get().me?.id;try{const d=await ctx.api('pulse/trends');if(user===ctx.get().me?.id){data=d;error='';at=Date.now()}}catch(e){error='Tendenze della community temporaneamente non disponibili.';at=Date.now()}finally{busy=false;refresh()}}
 function refresh(){const el=document.querySelector('#pulse-content');if(el){el.innerHTML=content();bindLinks()}}
 function bindLinks(){document.querySelectorAll('[data-pulse-topic]').forEach(b=>b.onclick=()=>ctx.filterTopic(b.dataset.pulseTopic));document.querySelectorAll('[data-pulse-city]').forEach(b=>b.onclick=()=>ctx.filterCity(b.dataset.pulseCity))}
 function restore(){hidden=[];save();ctx.render();ctx.toast('I post nascosti su questo dispositivo sono di nuovo visibili.')}
 function save(){try{localStorage.setItem('ms-hidden-posts',JSON.stringify(hidden.slice(-200)))}catch{}}
 function bind(){const identity=ctx.get().me?.id||'guest';if(identity!==who){who=identity;data=null;at=0}if(document.querySelector('#pulse-content')&&Date.now()-at>60000)load();bindLinks();document.querySelectorAll('[data-net-hide]').forEach(b=>b.onclick=()=>{hidden=[...new Set([...hidden,b.dataset.netHide])].slice(-200);save();const post=document.querySelector('#post-'+b.dataset.netHide);if(post){post.querySelectorAll('video').forEach(v=>v.pause());post.innerHTML='<div class="hidden-post">Post nascosto su questo dispositivo. <button data-undo-hide>Ripristina</button></div>';post.querySelector('button').onclick=()=>{hidden=hidden.filter(id=>id!==b.dataset.netHide);save();ctx.render()}}});document.querySelectorAll('[data-restore-feed]').forEach(b=>b.onclick=restore);document.querySelectorAll('[data-challenge-entry]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await ctx.api('pulse/entry',{post:b.dataset.challengeEntry});ctx.toast('Contributo aggiunto alla sfida della tua città.');ctx.challengeChanged()}catch(e){ctx.toast(e.message)}finally{b.disabled=false}})}
 return {html,bind,refresh,isHidden:id=>hidden.includes(id),hiddenCount:()=>hidden.length};
}
